import{_ as a,C as n,o as s,c as d,j as t,a as o,E as i,a2 as l}from"./chunks/framework.Di-jvWLj.js";const w=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/index.md","filePath":"getting-started/index.md","lastUpdated":1792229229000}'),c={name:"getting-started/index.md"},h={class:"info custom-block"};function u(p,e,g,f,m,b){const r=n("Badge");return s(),d("div",null,[e[9]||(e[9]=t("h1",{id:"introduction",tabindex:"-1"},[o("Introduction "),t("a",{class:"header-anchor",href:"#introduction","aria-label":'Permalink to "Introduction"'},"​")],-1)),e[10]||(e[10]=t("p",null,[o("chamberu is a TypeScript framework for "),t("strong",null,"self-hosted, trigger-driven AI agents"),o(". You write agents in your own repository, build them into a Docker image and run them on your own infrastructure. A webhook, a schedule or a manual call starts a run, and the run survives restarts, retries and approval pauses.")],-1)),e[11]||(e[11]=t("p",null,[o("The LLM side is the "),t("a",{href:"https://ai-sdk.dev",target:"_blank",rel:"noreferrer"},"Vercel AI SDK"),o(" v7. chamberu adds what the AI SDK leaves out on purpose: triggers, a run queue, persistence, concurrency control, approvals and a graceful shutdown.")],-1)),t("div",h,[e[8]||(e[8]=t("p",{class:"custom-block-title"},"Status",-1)),t("p",null,[e[0]||(e[0]=o("chamberu is pre-1.0. Only ",-1)),e[1]||(e[1]=t("a",{href:"/reference/"},[t("code",null,"@chamberu/core")],-1)),e[2]||(e[2]=o(" and its test helpers, ",-1)),e[3]||(e[3]=t("a",{href:"/reference/test-kit"},[t("code",null,"@chamberu/test-kit")],-1)),e[4]||(e[4]=o(", exist today. The scheduler, the HTTP API, the Postgres store, the GitHub connector, the UI and the deploy kit are planned; the ",-1)),e[5]||(e[5]=t("a",{href:"/roadmap"},"roadmap",-1)),e[6]||(e[6]=o(" lists them. Pages about planned work carry a ",-1)),i(r,{type:"warning",text:"Planned"}),e[7]||(e[7]=o(" badge.",-1))])]),e[12]||(e[12]=l('<h2 id="why-chamberu" tabindex="-1">Why chamberu? <a class="header-anchor" href="#why-chamberu" aria-label="Permalink to &quot;Why chamberu?&quot;">​</a></h2><p>The AI SDK runs the model and its tool loop, and stops there. An agent that reacts to webhooks and schedules also needs:</p><ul><li>a place to queue the work,</li><li>a way to survive a pod restart halfway through a run,</li><li>a guard against posting the same comment twice after a retry,</li><li>a way to wait a day for a human to approve a tool call.</li></ul><p>That usually means a hosted orchestrator, or a lot of glue code. chamberu is that layer as a library.</p><table tabindex="0"><thead><tr><th>Concern</th><th>AI SDK on its own</th><th>With <code>@chamberu/core</code></th></tr></thead><tbody><tr><td><strong>Intake</strong></td><td>You call <code>generateText</code> from your handler</td><td><code>dispatch()</code> stores a <code>queued</code> run; an <code>idempotencyKey</code> turns a redelivery into the existing run</td></tr><tr><td><strong>Concurrency</strong></td><td>Two webhooks for the same issue race each other</td><td>One run at a time per <code>concurrencyKey</code>, enforced through the store across replicas</td></tr><tr><td><strong>Durability</strong></td><td>A crash loses the conversation</td><td>A checkpoint after every step; a recovered run continues from the latest one</td></tr><tr><td><strong>Side effects</strong></td><td>A retried tool call posts again</td><td><code>defineEffectTool()</code> records each result per effect key and can check the remote system first</td></tr><tr><td><strong>Approvals</strong></td><td>You build the pause, the storage and the callback</td><td>The run waits in <code>waiting</code> with a signed resume token; <code>resume(token, decision)</code> continues it</td></tr><tr><td><strong>Limits</strong></td><td><code>stopWhen</code> per call</td><td><code>maxSteps</code>, <code>maxTokens</code> and <code>timeoutMs</code> per run, settled as <code>completed</code> or <code>failed</code></td></tr><tr><td><strong>Shutdown</strong></td><td>Runs die with the process</td><td><code>drain()</code> waits for in-flight runs, then marks the rest <code>interrupted</code> for another replica</td></tr></tbody></table><h2 id="design-principles" tabindex="-1">Design principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design principles&quot;">​</a></h2><ul><li><strong>Triggers first.</strong> Every run starts from one normalized <a href="/guide/triggers">trigger envelope</a>. Deduplication and concurrency are decided at intake, before any model call.</li><li><strong>Self-hosted.</strong> Agents run in your process, on your cluster, with your provider keys. Nothing phones home and there is no paid console.</li><li><strong>No orchestrator server.</strong> Runs, leases, locks and idempotency keys live in a <a href="/stores/">pluggable store</a>. Replicas coordinate through that store; Redis is never required.</li><li><strong>Built on the AI SDK, not around it.</strong> <code>LanguageModel</code>, <code>ModelMessage</code> and <code>ToolSet</code> pass through unchanged. If you know <code>tool()</code> and <code>ToolLoopAgent</code>, you know how to write a chamberu tool.</li><li><strong>A small concept surface.</strong> About ten concepts: App, Agent, Trigger, Run, Step, State, Tool, Workspace, Notifier, Store. The core ships Agent, Trigger, Run, Step, State, Tool, Notifier and Store.</li><li><strong>No spam.</strong> Retries and restarts must not repeat comments, pushes or notifications. That is what <a href="/guide/effect-tools">effect tools</a> and notifier idempotency keys are for.</li></ul><h2 id="how-it-compares" tabindex="-1">How it compares <a class="header-anchor" href="#how-it-compares" aria-label="Permalink to &quot;How it compares&quot;">​</a></h2><p>chamberu sits next to several good tools. The difference is mostly where the orchestration runs and who owns it.</p><table tabindex="0"><thead><tr><th>Tool</th><th>What it is</th><th>Where chamberu differs</th></tr></thead><tbody><tr><td><strong>Inngest</strong></td><td>Event-driven durable functions with step memoization, run by the Inngest server (cloud or self-hosted)</td><td>No separate server: the engine is a library and the store is your database</td></tr><tr><td><strong>Trigger.dev</strong></td><td>A platform for background jobs and AI tasks, with its own workers and dashboard (cloud or self-hosted)</td><td>Runs in your own Node process; the deploy kit is a plain Docker image and Helm chart</td></tr><tr><td><strong>Mastra</strong></td><td>A TypeScript agent framework with its own agent, workflow and memory abstractions</td><td>Keeps AI SDK types as they are and focuses on triggers, durable runs and operations</td></tr><tr><td><strong>Cloudflare Agents</strong></td><td>Stateful agents on Durable Objects</td><td>Not tied to a vendor runtime: any Node 22+ host and any store that passes the contract</td></tr><tr><td><strong>Workflow SDK</strong> (<code>workflow</code>, <code>@ai-sdk/workflow</code>)</td><td>Durable functions through <code>&#39;use workflow&#39;</code> and <code>&#39;use step&#39;</code> directives with deterministic replay, wired in through a bundler integration</td><td>Uses step checkpoints instead of replay, so plain code runs as written, without a compiler step</td></tr></tbody></table><p>Each of these is a better fit in some setups: if you already run Inngest or Trigger.dev, or deploy to Cloudflare or Vercel, use what fits that platform. chamberu targets one owner running their agents on their own cluster.</p><h2 id="what-ships-today" tabindex="-1">What ships today <a class="header-anchor" href="#what-ships-today" aria-label="Permalink to &quot;What ships today&quot;">​</a></h2><p><code>@chamberu/core</code> contains:</p><ul><li><a href="/guide/agents"><code>defineAgent()</code></a> and the trigger builders <code>cron()</code>, <code>http()</code> and <code>manual()</code></li><li>the <a href="/reference/#runengine"><code>RunEngine</code></a>: dispatch, scheduling, execution, checkpoints, budgets, approvals, cancel, drain and recovery</li><li><a href="/guide/effect-tools">effect tools</a> and <a href="/guide/state">agent state</a></li><li>the <a href="/stores/">store contract</a> and <a href="/stores/memory"><code>MemoryStore</code></a></li><li>the <a href="/guide/notifiers"><code>INotifier</code></a> interface</li></ul><p><code>@chamberu/test-kit</code> adds the store contract suite and a controllable clock for tests.</p><p>The engine starts runs only through <code>engine.dispatch()</code>. Firing cron triggers, receiving webhooks and serving an HTTP or MCP API belong to the planned <a href="/roadmap"><code>@chamberu/scheduler</code> and <code>@chamberu/http</code></a> packages.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/getting-started/installation">Installation</a>: install the core and a model provider.</li><li><a href="/getting-started/quick-start">Quick Start</a>: define an agent and run it once.</li><li><a href="/guide/">Guide</a>: the concepts, one page each.</li></ul>',18))])}const k=a(c,[["render",u]]);export{w as __pageData,k as default};
